package decorator

import (
	"fmt"
	"io"
	"net/http"
	"time"
)

// PROBLEM
//
// Three handlers, and each one pastes the same three jobs around its real
// work: check the token, time the request, write a log line. Adding a fourth
// job, or changing one, means editing every handler. And copies drift:
// ExportBefore never got the token check, so anyone can export.
//
// TRY IT
//
// Read TestBefore_ExportForgotAuth in decorator_test.go: /export answers 200
// to a request with no token at all. Then count the lines you would edit to
// add request timing to every route.
//
// Do not edit this file. Your work goes in after.go.

// OrdersBefore serves the order list, with auth, timing and logging pasted in.
func OrdersBefore(token string, log io.Writer) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		if r.Header.Get("X-Token") != token {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			fmt.Fprintf(log, "%s %s %d %s\n", r.Method, r.URL.Path, http.StatusUnauthorized, time.Since(start))
			return
		}
		fmt.Fprint(w, "orders")
		fmt.Fprintf(log, "%s %s %d %s\n", r.Method, r.URL.Path, http.StatusOK, time.Since(start))
	}
}

// ReportBefore serves a report, with the same three jobs pasted in again.
func ReportBefore(token string, log io.Writer) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		if r.Header.Get("X-Token") != token {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			fmt.Fprintf(log, "%s %s %d %s\n", r.Method, r.URL.Path, http.StatusUnauthorized, time.Since(start))
			return
		}
		fmt.Fprint(w, "report")
		fmt.Fprintf(log, "%s %s %d %s\n", r.Method, r.URL.Path, http.StatusOK, time.Since(start))
	}
}

// ExportBefore serves an export. Whoever pasted it in left out the token check.
func ExportBefore(token string, log io.Writer) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		fmt.Fprint(w, "export")
		fmt.Fprintf(log, "%s %s %d %s\n", r.Method, r.URL.Path, http.StatusOK, time.Since(start))
	}
}

// RoutesBefore serves the three handlers.
func RoutesBefore(token string, log io.Writer) http.Handler {
	mux := http.NewServeMux()
	mux.Handle("GET /orders", OrdersBefore(token, log))
	mux.Handle("GET /report", ReportBefore(token, log))
	mux.Handle("GET /export", ExportBefore(token, log))
	return mux
}
